// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }
    function testFuzz_property(address nonOwner, uint256 amount) public {
        vm.assume(nonOwner != address(this));
        vm.assume(amount > 0);
        vm.deal(address(c), amount);

        bool ok;
        vm.prank(nonOwner);
        try c.withdrawAll(address(0)) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(!ok || nonOwner == c.owner());
    }
}
